{"command":"python3 -c '
import subprocess
out = subprocess.check_output(["./executable", "/tmp/testbytes.bin", "--color=always", "--color-scheme=gradient"]).decode("utf-8")
import re
colors = {}
for b in range(256):
    # find byte in hex representation e.g. " 00 " or " 01 "
    hex_str = f"{b:02x}"
    pattern = re.compile(r"\\x1b\[38;2;(\d+);(\d+);(\d+)m" + hex_str)
    m = pattern.search(repr(out))
    if m:
        colors[b] = (int(m.group(1)), int(m.group(2)), int(m.group(3)))
    else:
        # check if standard color escape
        pattern2 = re.compile(r"\\x1b\[(\d+)m" + hex_str)
        m2 = pattern2.search(repr(out))
        if m2:
            colors[b] = int(m2.group(1))

print("Gradient colors for 256 bytes:")
for b in range(256):
    print(f"byte {b:3d} (0x{b:02x}): {colors.get(b)}")
'"}

