{"command":"python3 -c '
import subprocess

def raw_hex_width(base, group_size):
    dpb = 2 if base in ["hex", "hexadecimal"] else (8 if base in ["binary", "bin"] else 3)
    return 8 * dpb + (8 // group_size - 1)

def calc_width(n, border, show_pos, show_char, base, group_size):
    rhw = raw_hex_width(base, group_size)
    if border in ["unicode", "ascii"]:
        w = 1 # left border
        if show_pos: w += 9 # pos + div
        w += n * (rhw + 2) + (n - 1) # hex panels + inner divs
        if show_char:
            w += 1 + n * 8 + (n - 1) # div + char panels + inner divs
        w += 1 # right border
        return w
    else:
        w = 1 # left space
        if show_pos: w += 10 # pos + 2 spaces
        w += n * rhw + (n - 1) * 3 + 2 # hex panels + 3 spaces between + 2 trailing
        if show_char:
            w += n * 8 + (n - 1) * 1 + 1 # char panels + 1 space between + 1 trailing
        return w

# Test against executable output lengths
for base in ["hex", "octal", "binary"]:
    for g in [1, 2, 4, 8]:
        if base != "hex" and g != 1: continue
        for border in ["unicode", "ascii", "none"]:
            for show_pos in [True, False]:
                for show_char in [True, False]:
                    cfg = [f"--base={base}", f"-g={g}", f"--border={border}"]
                    if not show_pos: cfg.append("--no-position")
                    if not show_char: cfg.append("--no-characters")
                    cmd = ["./executable", "/tmp/testbytes.bin", "--color=never", "-n", "32", "--panels=2"] + cfg
                    out = subprocess.check_output(cmd).decode("utf-8")
                    actual_len = len(out.splitlines()[0])
                    expected_len = calc_width(2, border, show_pos, show_char, base, g)
                    if actual_len != expected_len:
                        print(f"MISMATCH! base={base} g={g} border={border} pos={show_pos} char={show_char}: actual={actual_len} expected={expected_len}")

print("All row width tests completed.")
'"}

