        if show_pos: w += 9 # pos + div
        w += n * (rhw + 2) + (n - 1) # hex panels + inner divs
        if show_char:
            w += 1 + n * 8 + (n - 1) # div + char panels + inner divs
        w += 1 # right border
        return w
    else:
