        w += n * rhw + (n - 1) * 3 + 2 # hex panels + 3 spaces between + 2 trailing
        if show_char:
            w += n * 8 + (n - 1) * 1 + 1 # char panels + 1 space between + 1 trailing
        return w

# Test against executable output lengths
