fn parse_byte_count(flag_name: &str, s: &str, block_size: u64, allow_negative: bool) -> Result<(u64, bool), String> {
    let mut rest = s;
    let mut is_negative = false;
    if rest.starts_with('-') {
        if !allow_negative {
            return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    negative offset specified, but only positive offsets (counts) are accepted in this context",
                flag_name, s
            ));
        }
        is_negative = true;
        rest = &rest[1..];
    }

    if rest.starts_with("0x") || rest.starts_with("0X") {
        let hex_str = &rest[2..];
        if hex_str.is_empty() {
            return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string",
                flag_name, s
            ));
        }
        match u64::from_str_radix(hex_str, 16) {
            Ok(v) => Ok((v, is_negative)),
            Err(_) => Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string",
                flag_name, s
            )),
        }
    } else {
        let split_pos = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
        let num_str = &rest[..split_pos];
        let unit_str = &rest[split_pos..];

        if num_str.is_empty() {
            return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]",
                flag_name, s, s
            ));
        }

        let base_num: u64 = match num_str.parse() {
            Ok(n) => n,
            Err(_) => return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]",
                flag_name, s, s
            )),
        };

        let multiplier: u64 = match unit_str {
            "" => 1,
            "kB" | "kb" | "KB" => 1000,
            "MB" | "mb" | "Mb" => 1000 * 1000,
            "GB" | "gb" | "Gb" => 1000 * 1000 * 1000,
            "TB" | "tb" | "Tb" => 1000 * 1000 * 1000 * 1000,
            "PB" | "pb" | "Pb" => 1000 * 1000 * 1000 * 1000 * 1000,
            "KiB" | "kib" | "KIB" => 1024,
            "MiB" | "mib" | "MIB" => 1024 * 1024,
            "GiB" | "gib" | "GIB" => 1024 * 1024 * 1024,
            "TiB" | "tib" | "TIB" => 1024 * 1024 * 1024 * 1024,
            "PiB" | "pib" | "PIB" => 1024 * 1024 * 1024 * 1024 * 1024,
            "block" | "blocks" => block_size,
            u => return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    invalid unit \"{}\"",
                flag_name, s, u
            )),
        };

        Ok((base_num * multiplier, is_negative))
    }
}

fn parse_args() -> Config {
    let args: Vec<String> = env::args().collect();
    let mut config = Config::default();

    let mut panels_set = false;
    let mut width_set = false;

    // First pass to find block-size if specified
    let mut block_size = 512;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--block-size" && i + 1 < args.len() {
            if let Ok((val, _)) = parse_byte_count("--block-size", &args[i + 1], 512, false) {
                block_size = val;
            }
        } else if arg.starts_with("--block-size=") {
            let val_str = &arg["--block-size=".len()..];
            if let Ok((val, _)) = parse_byte_count("--block-size", val_str, 512, false) {
                block_size = val;
            }
        }
        i += 1;
    }
    config.block_size = block_size;

    i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "-h" {
            print_help(false);
            process::exit(0);
        } else if arg == "--help" {
            print_help(true);
            process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("hexyl 0.16.0");
            process::exit(0);
        } else if arg == "-v" || arg == "--no-squeezing" {
            config.squeezing = false;
        } else if arg == "-p" || arg == "--plain" {
            config.show_characters = false;
            config.show_position = false;
            config.border_style = BorderStyle::None;
            config.color_mode = ColorMode::Never;
        } else if arg == "-C" || arg == "--characters" {
            config.show_characters = true;
        } else if arg == "--no-characters" {
            config.show_characters = false;
        } else if arg == "-P" || arg == "--no-position" {
            config.show_position = false;
        } else if arg == "--print-color-table" {
            config.print_color_table = true;
        } else if arg == "-i" || arg == "--include" {
            config.include = true;
        } else if arg == "-e" {
            config.endianness = Endianness::Little;
        } else if arg == "--block-size" {
            i += 1; // already parsed in first pass
        } else if arg.starts_with("--block-size=") {
            // already parsed
        } else if arg == "-n" || arg == "--length" || arg == "-c" || arg == "--bytes" || arg == "-l" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--length <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match parse_byte_count("--length", &args[i], config.block_size, false) {
                Ok((val, _)) => config.length = Some(val),
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--length=") || arg.starts_with("--bytes=") {
            let val_str = if arg.starts_with("--length=") { &arg["--length=".len()..] } else { &arg["--bytes=".len()..] };
            match parse_byte_count("--length", val_str, config.block_size, false) {
                Ok((val, _)) => config.length = Some(val),
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("-n") && arg.len() > 2 {
            let val_str = &arg[2..];
            match parse_byte_count("--length", val_str, config.block_size, false) {
                Ok((val, _)) => config.length = Some(val),
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg == "-s" || arg == "--skip" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--skip <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match parse_byte_count("--skip", &args[i], config.block_size, true) {
                Ok((val, is_neg)) => {
                    let signed_val = if is_neg { -(val as i64) } else { val as i64 };
                    config.skip = Some(signed_val);
                }
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--skip=") {
            let val_str = &arg["--skip=".len()..];
            match parse_byte_count("--skip", val_str, config.block_size, true) {
                Ok((val, is_neg)) => {
                    let signed_val = if is_neg { -(val as i64) } else { val as i64 };
                    config.skip = Some(signed_val);
                }
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg == "-o" || arg == "--display-offset" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--display-offset <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match parse_byte_count("--display-offset", &args[i], config.block_size, false) {
                Ok((val, _)) => config.display_offset = val,
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--display-offset=") {
            let val_str = &arg["--display-offset=".len()..];
            match parse_byte_count("--display-offset", val_str, config.block_size, false) {
                Ok((val, _)) => config.display_offset = val,
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg == "--color" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--color <WHEN>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "always" => config.color_mode = ColorMode::Always,
                "auto" => config.color_mode = ColorMode::Auto,
                "never" => config.color_mode = ColorMode::Never,
                "force" => config.color_mode = ColorMode::Force,
                v => {
                    eprintln!("error: invalid value '{}' for '--color <WHEN>'\n  [possible values: always, auto, never, force]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--color=") {
            let v = &arg["--color=".len()..];
            match v {
                "always" => config.color_mode = ColorMode::Always,
                "auto" => config.color_mode = ColorMode::Auto,
                "never" => config.color_mode = ColorMode::Never,
                "force" => config.color_mode = ColorMode::Force,
                _ => {
                    eprintln!("error: invalid value '{}' for '--color <WHEN>'\n  [possible values: always, auto, never, force]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--border" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--border <STYLE>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "unicode" => config.border_style = BorderStyle::Unicode,
                "ascii" => config.border_style = BorderStyle::Ascii,
                "none" => config.border_style = BorderStyle::None,
                v => {
                    eprintln!("error: invalid value '{}' for '--border <STYLE>'\n  [possible values: unicode, ascii, none]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--border=") {
            let v = &arg["--border=".len()..];
            match v {
                "unicode" => config.border_style = BorderStyle::Unicode,
                "ascii" => config.border_style = BorderStyle::Ascii,
                "none" => config.border_style = BorderStyle::None,
                _ => {
                    eprintln!("error: invalid value '{}' for '--border <STYLE>'\n  [possible values: unicode, ascii, none]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--character-table" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--character-table <FORMAT>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "default" => config.character_table = CharTable::Default,
                "ascii" => config.character_table = CharTable::Ascii,
                "codepage-1047" => config.character_table = CharTable::Codepage1047,
                "codepage-437" => config.character_table = CharTable::Codepage437,
                "braille" => config.character_table = CharTable::Braille,
                v => {
                    eprintln!("error: invalid value '{}' for '--character-table <FORMAT>'\n  [possible values: default, ascii, codepage-1047, codepage-437, braille]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--character-table=") {
            let v = &arg["--character-table=".len()..];
            match v {
                "default" => config.character_table = CharTable::Default,
                "ascii" => config.character_table = CharTable::Ascii,
                "codepage-1047" => config.character_table = CharTable::Codepage1047,
                "codepage-437" => config.character_table = CharTable::Codepage437,
                "braille" => config.character_table = CharTable::Braille,
                _ => {
                    eprintln!("error: invalid value '{}' for '--character-table <FORMAT>'\n  [possible values: default, ascii, codepage-1047, codepage-437, braille]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--color-scheme" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--color-scheme <FORMAT>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "default" => config.color_scheme = ColorScheme::Default,
                "gradient" => config.color_scheme = ColorScheme::Gradient,
                v => {
                    eprintln!("error: invalid value '{}' for '--color-scheme <FORMAT>'\n  [possible values: default, gradient]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--color-scheme=") {
            let v = &arg["--color-scheme=".len()..];
            match v {
                "default" => config.color_scheme = ColorScheme::Default,
                "gradient" => config.color_scheme = ColorScheme::Gradient,
                _ => {
                    eprintln!("error: invalid value '{}' for '--color-scheme <FORMAT>'\n  [possible values: default, gradient]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--panels" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--panels <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            let val_str = &args[i];
            if val_str == "auto" {
                config.panels = Panels::Auto;
            } else if val_str == "0" {
                eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                process::exit(1);
            } else if let Ok(n) = val_str.parse::<usize>() {
                config.panels = Panels::Fixed(n);
            } else {
                eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string", val_str);
                process::exit(1);
            }
            panels_set = true;
        } else if arg.starts_with("--panels=") {
            let val_str = &arg["--panels=".len()..];
            if val_str == "auto" {
                config.panels = Panels::Auto;
            } else if val_str == "0" {
                eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                process::exit(1);
            } else if let Ok(n) = val_str.parse::<usize>() {
                config.panels = Panels::Fixed(n);
            } else {
                eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string", val_str);
                process::exit(1);
            }
            panels_set = true;
        } else if arg == "-g" || arg == "--group-size" || arg == "--groupsize" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--group-size <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "1" => config.group_size = 1,
                "2" => config.group_size = 2,
                "4" => config.group_size = 4,
                "8" => config.group_size = 8,
                v => {
                    eprintln!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("-g=") || arg.starts_with("--group-size=") || arg.starts_with("--groupsize=") {
            let idx = arg.find('=').unwrap();
            let v = &arg[idx + 1..];
            match v {
                "1" => config.group_size = 1,
                "2" => config.group_size = 2,
                "4" => config.group_size = 4,
                "8" => config.group_size = 8,
                _ => {
                    eprintln!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--endianness" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--endianness <FORMAT>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "little" => config.endianness = Endianness::Little,
                "big" => config.endianness = Endianness::Big,
                v => {
                    eprintln!("error: invalid value '{}' for '--endianness <FORMAT>'\n  [possible values: little, big]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--endianness=") {
            let v = &arg["--endianness=".len()..];
            match v {
                "little" => config.endianness = Endianness::Little,
                "big" => config.endianness = Endianness::Big,
                _ => {
                    eprintln!("error: invalid value '{}' for '--endianness <FORMAT>'\n  [possible values: little, big]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "-b" || arg == "--base" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--base <B>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "hexadecimal" | "hex" | "x" => config.base = Base::Hexadecimal,
                "binary" | "bin" | "b" => config.base = Base::Binary,
                "octal" | "oct" | "o" => config.base = Base::Octal,
                "decimal" | "dec" | "d" => config.base = Base::Decimal,
                _ => {
                    eprintln!("Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".");
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--base=") {
            let v = &arg["--base=".len()..];
            match v {
                "hexadecimal" | "hex" | "x" => config.base = Base::Hexadecimal,
                "binary" | "bin" | "b" => config.base = Base::Binary,
                "octal" | "oct" | "o" => config.base = Base::Octal,
                "decimal" | "dec" | "d" => config.base = Base::Decimal,
                _ => {
                    eprintln!("Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".");
                    process::exit(1);
                }
            }
        } else if arg == "--terminal-width" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--terminal-width <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            if let Ok(w) = args[i].parse::<usize>() {
                config.terminal_width = Some(w);
            } else {
                eprintln!("error: invalid value '{}' for '--terminal-width <N>'", args[i]);
                process::exit(2);
            }
            width_set = true;
        } else if arg.starts_with("--terminal-width=") {
            let v = &arg["--terminal-width=".len()..];
            if let Ok(w) = v.parse::<usize>() {
                config.terminal_width = Some(w);
            } else {
                eprintln!("error: invalid value '{}' for '--terminal-width <N>'", v);
                process::exit(2);
            }
            width_set = true;
        } else if arg == "--completion" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--completion <SHELL>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "bash" | "elvish" | "fish" | "powershell" | "zsh" => config.completion = Some(args[i].clone()),
                v => {
                    eprintln!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--completion=") {
            let v = &arg["--completion=".len()..];
            match v {
                "bash" | "elvish" | "fish" | "powershell" | "zsh" => config.completion = Some(v.to_string()),
                _ => {
                    eprintln!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--" {
            i += 1;
            if i < args.len() {
                config.file = Some(args[i].clone());
            }
            break;
        } else if arg.starts_with('-') && arg != "-" {
            eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", arg, arg, arg);
            process::exit(2);
        } else {
            config.file = Some(arg.clone());
        }

        i += 1;
    }

    if panels_set && width_set {
        eprintln!("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nUsage: executable --panels <N> [FILE]\n\nFor more information, try '--help'.");
        process::exit(2);
    }

    config
}

fn print_color_table() {
    println!("hexyl color reference:\n");
    println!("\x1b[90m⋄ NULL bytes (0x00)");
    println!("\x1b[39m\x1b[36ma ASCII printable characters (0x20 - 0x7E)");
    println!("\x1b[39m\x1b[32m_ ASCII whitespace (0x09 - 0x0D, 0x20)");
    println!("\x1b[39m\x1b[32m• ASCII control characters (except NULL and whitespace)");
    println!("\x1b[39m\x1b[33m× Non-ASCII bytes (0x80 - 0xFF)");
    print!("\x1b[39m");
}

fn print_completion(shell: &str) {
    match shell {
        "bash" => println!(
r#"_hexyl() {
    local i cur prev opts cmd
    COMPREPLY=()
    if [[ "${BASH_VERSINFO[0]}" -ge 4 ]]; then
        cur="$2"
    else
        cur="${COMP_WORDS[COMP_CWORD]}"
    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${COMP_WORDS[@]}"; do
        case "$i" in
            hexyl)
                cmd="hexyl"
                ;;
            *)
                ;;
        esac
    done

    case "${cmd}" in
        hexyl)
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "-n --length -c --bytes -l -s --skip --block-size -v --no-squeezing --color --border -p --plain --no-characters -C --characters --character-table --color-scheme -P --no-position -o --display-offset --panels -g --group-size --groupsize --endianness -e -b --base --terminal-width --print-color-table -i --include --completion -h --help -V --version" -- "${cur}") )
                return 0
            fi
            case "${prev}" in
                --length|-n|-c|--bytes|-l)
                    COMPREPLY=($(compgen -W "64 4KiB 0xff" -- "${cur}"))
                    return 0
                    ;;
                --color)
                    COMPREPLY=($(compgen -W "always auto never force" -- "${cur}"))
                    return 0
                    ;;
                --border)
                    COMPREPLY=($(compgen -W "unicode ascii none" -- "${cur}"))
                    return 0
                    ;;
                --character-table)
                    COMPREPLY=($(compgen -W "default ascii codepage-1047 codepage-437 braille" -- "${cur}"))
                    return 0
                    ;;
                --color-scheme)
                    COMPREPLY=($(compgen -W "default gradient" -- "${cur}"))
                    return 0
                    ;;
                --group-size|-g|--groupsize)
                    COMPREPLY=($(compgen -W "1 2 4 8" -- "${cur}"))
                    return 0
                    ;;
                --endianness)
                    COMPREPLY=($(compgen -W "little big" -- "${cur}"))
                    return 0
                    ;;
                --base|-b)
                    COMPREPLY=($(compgen -W "binary octal decimal hexadecimal" -- "${cur}"))
                    return 0
                    ;;
                --completion)
                    COMPREPLY=($(compgen -W "bash elvish fish powershell zsh" -- "${cur}"))
                    return 0
                    ;;
                *)
                    COMPREPLY=()
                    ;;
            esac
            ;;
    esac
}

complete -F _hexyl hexyl"#
        ),
        _ => {}
    }
}

fn parse_color_str(s: &str, default_esc: &str) -> String {
    match s.to_lowercase().as_str() {
        "black" => "\x1b[30m".to_string(),
        "red" => "\x1b[31m".to_string(),
        "green" => "\x1b[32m".to_string(),
        "yellow" => "\x1b[33m".to_string(),
        "blue" => "\x1b[34m".to_string(),
        "magenta" => "\x1b[35m".to_string(),
        "cyan" => "\x1b[36m".to_string(),
        "white" => "\x1b[37m".to_string(),
        "bright black" => "\x1b[90m".to_string(),
        "bright red" => "\x1b[91m".to_string(),
        "bright green" => "\x1b[92m".to_string(),
        "bright yellow" => "\x1b[93m".to_string(),
        "bright blue" => "\x1b[94m".to_string(),
        "bright magenta" => "\x1b[95m".to_string(),
        "bright cyan" => "\x1b[96m".to_string(),
        "bright white" => "\x1b[97m".to_string(),
        hex if hex.starts_with('#') && hex.len() == 7 => {
            if let (Ok(r), Ok(g), Ok(b)) = (
                u8::from_str_radix(&hex[1..3], 16),
                u8::from_str_radix(&hex[3..5], 16),
                u8::from_str_radix(&hex[5..7], 16),
            ) {
                format!("\x1b[38;2;{};{};{}m", r, g, b)
            } else {
                default_esc.to_string()
            }
        }
        _ => default_esc.to_string(),
    }
}

fn get_byte_color(b: u8, config: &Config) -> String {
    if config.color_scheme == ColorScheme::Gradient {
        match b {
            0x00 => "\x1b[38;2;100;100;100m".to_string(),
            0x01..=0x1F => {
                let i = (b - 1) as f64;
                let r = (255.0 - (123.0 * i / 30.0)).round() as u8;
                format!("\x1b[38;2;{};000;255m", r)
            }
            0x20..=0x7E => {
                let i = (b - 0x20) as f64;
                let g = (128.0 + (125.0 * i / 94.0)).round() as u8;
                let b_val = (255.0 - (126.0 * i / 94.0)).round() as u8;
                format!("\x1b[38;2;000;{:03};{:03}m", g, b_val)
            }
            0x7F => "\x1b[38;2;064;128;000m".to_string(),
            0x80..=0xD4 => {
                let i = (b - 0x80) as f64;
                let g = (253.0 * i / 84.0).round() as u8;
                format!("\x1b[38;2;255;{:03};000m", g)
            }
            0xD5..=0xFF => {
                let i = (b - 0xD5) as f64;
                let b_val = (3.0 + (246.0 * i / 42.0)).round() as u8;
                format!("\x1b[38;2;255;255;{:03}m", b_val)
            }
        }
    } else {
        match b {
            0x00 => {
                let env_val = env::var("HEXYL_COLOR_NULL").unwrap_or_default();
                parse_color_str(&env_val, "\x1b[90m")
            }
            0x09..=0x0D | 0x20 => {
                let env_val = env::var("HEXYL_COLOR_ASCII_WHITESPACE").unwrap_or_default();
                parse_color_str(&env_val, "\x1b[32m")
            }
            0x01..=0x08 | 0x0E..=0x1F | 0x7F => {
                let env_val = env::var("HEXYL_COLOR_ASCII_OTHER").unwrap_or_default();
                parse_color_str(&env_val, "\x1b[32m")
            }
            0x21..=0x7E => {
                let env_val = env::var("HEXYL_COLOR_ASCII_PRINTABLE").unwrap_or_default();
                parse_color_str(&env_val, "\x1b[36m")
            }
            0x80..=0xFF => {
                let env_val = env::var("HEXYL_COLOR_NONASCII").unwrap_or_default();
                parse_color_str(&env_val, "\x1b[33m")
            }
        }
    }
}

fn get_offset_color() -> String {
    let env_val = env::var("HEXYL_COLOR_OFFSET").unwrap_or_default();
    parse_color_str(&env_val, "\x1b[90m")
}

