fn parse_byte_count(flag_name: &str, s: &str, block_size: u64, allow_negative: bool) -> Result<(u64, bool), String> {
    let mut rest = s;
    let mut is_negative = false;
    if rest.starts_with('-') {
        if !allow_negative {
            return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    negative offset specified, but only positive offsets (counts) are accepted in this context",
                flag_name, s
            ));
        }
        is_negative = true;
        rest = &rest[1..];
    }

    if rest.starts_with("0x") || rest.starts_with("0X") {
        let hex_str = &rest[2..];
        if hex_str.is_empty() {
            return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string",
                flag_name, s
            ));
        }
        match u64::from_str_radix(hex_str, 16) {
            Ok(v) => Ok((v, is_negative)),
            Err(_) => Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string",
                flag_name, s
            )),
        }
    } else {
        let split_pos = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
        let num_str = &rest[..split_pos];
        let unit_str = &rest[split_pos..];

        if num_str.is_empty() {
            return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]",
                flag_name, s, s
            ));
        }

        let base_num: u64 = match num_str.parse() {
            Ok(n) => n,
            Err(_) => return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]",
                flag_name, s, s
            )),
        };

        let multiplier: u64 = match unit_str {
            "" => 1,
            "kB" | "kb" | "KB" => 1000,
            "MB" | "mb" | "Mb" => 1000 * 1000,
            "GB" | "gb" | "Gb" => 1000 * 1000 * 1000,
            "TB" | "tb" | "Tb" => 1000 * 1000 * 1000 * 1000,
            "PB" | "pb" | "Pb" => 1000 * 1000 * 1000 * 1000 * 1000,
            "KiB" | "kib" | "KIB" => 1024,
            "MiB" | "mib" | "MIB" => 1024 * 1024,
            "GiB" | "gib" | "GIB" => 1024 * 1024 * 1024,
            "TiB" | "tib" | "TIB" => 1024 * 1024 * 1024 * 1024,
            "PiB" | "pib" | "PIB" => 1024 * 1024 * 1024 * 1024 * 1024,
            "block" | "blocks" => block_size,
            u => return Err(format!(
                "Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    invalid unit \"{}\"",
                flag_name, s, u
            )),
        };

        Ok((base_num * multiplier, is_negative))
    }
}

fn parse_args() -> Config {
    let args: Vec<String> = env::args().collect();
    let mut config = Config::default();

    let mut panels_set = false;
    let mut width_set = false;

    // First pass to find block-size if specified
    let mut block_size = 512;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--block-size" && i + 1 < args.len() {
            if let Ok((val, _)) = parse_byte_count("--block-size", &args[i + 1], 512, false) {
                block_size = val;
            }
        } else if arg.starts_with("--block-size=") {
            let val_str = &arg["--block-size=".len()..];
            if let Ok((val, _)) = parse_byte_count("--block-size", val_str, 512, false) {
                block_size = val;
            }
        }
        i += 1;
    }
    config.block_size = block_size;

    i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "-h" {
            print_help(false);
            process::exit(0);
        } else if arg == "--help" {
            print_help(true);
            process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("hexyl 0.16.0");
            process::exit(0);
        } else if arg == "-v" || arg == "--no-squeezing" {
            config.squeezing = false;
        } else if arg == "-p" || arg == "--plain" {
            config.show_characters = false;
            config.show_position = false;
            config.border_style = BorderStyle::None;
            config.color_mode = ColorMode::Never;
        } else if arg == "-C" || arg == "--characters" {
            config.show_characters = true;
        } else if arg == "--no-characters" {
            config.show_characters = false;
        } else if arg == "-P" || arg == "--no-position" {
            config.show_position = false;
        } else if arg == "--print-color-table" {
            config.print_color_table = true;
        } else if arg == "-i" || arg == "--include" {
            config.include = true;
        } else if arg == "-e" {
            config.endianness = Endianness::Little;
        } else if arg == "--block-size" {
            i += 1; // already parsed in first pass
        } else if arg.starts_with("--block-size=") {
            // already parsed
        } else if arg == "-n" || arg == "--length" || arg == "-c" || arg == "--bytes" || arg == "-l" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--length <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match parse_byte_count("--length", &args[i], config.block_size, false) {
                Ok((val, _)) => config.length = Some(val),
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--length=") || arg.starts_with("--bytes=") {
            let val_str = if arg.starts_with("--length=") { &arg["--length=".len()..] } else { &arg["--bytes=".len()..] };
            match parse_byte_count("--length", val_str, config.block_size, false) {
                Ok((val, _)) => config.length = Some(val),
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("-n") && arg.len() > 2 {
            let val_str = &arg[2..];
            match parse_byte_count("--length", val_str, config.block_size, false) {
                Ok((val, _)) => config.length = Some(val),
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg == "-s" || arg == "--skip" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--skip <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match parse_byte_count("--skip", &args[i], config.block_size, true) {
                Ok((val, is_neg)) => {
                    let signed_val = if is_neg { -(val as i64) } else { val as i64 };
                    config.skip = Some(signed_val);
                }
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--skip=") {
            let val_str = &arg["--skip=".len()..];
            match parse_byte_count("--skip", val_str, config.block_size, true) {
                Ok((val, is_neg)) => {
                    let signed_val = if is_neg { -(val as i64) } else { val as i64 };
                    config.skip = Some(signed_val);
                }
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg == "-o" || arg == "--display-offset" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--display-offset <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match parse_byte_count("--display-offset", &args[i], config.block_size, false) {
                Ok((val, _)) => config.display_offset = val,
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--display-offset=") {
            let val_str = &arg["--display-offset=".len()..];
            match parse_byte_count("--display-offset", val_str, config.block_size, false) {
                Ok((val, _)) => config.display_offset = val,
                Err(e) => {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
