            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--panels <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            let val_str = &args[i];
            if val_str == "auto" {
                config.panels = Panels::Auto;
            } else if val_str == "0" {
                eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                process::exit(1);
            } else if let Ok(n) = val_str.parse::<usize>() {
                config.panels = Panels::Fixed(n);
            } else {
                eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string", val_str);
                process::exit(1);
            }
            panels_set = true;
        } else if arg.starts_with("--panels=") {
            let val_str = &arg["--panels=".len()..];
            if val_str == "auto" {
                config.panels = Panels::Auto;
            } else if val_str == "0" {
                eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                process::exit(1);
            } else if let Ok(n) = val_str.parse::<usize>() {
                config.panels = Panels::Fixed(n);
            } else {
                eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string", val_str);
                process::exit(1);
            }
            panels_set = true;
        } else if arg == "-g" || arg == "--group-size" || arg == "--groupsize" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--group-size <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "1" => config.group_size = 1,
                "2" => config.group_size = 2,
                "4" => config.group_size = 4,
                "8" => config.group_size = 8,
