                "default" => config.character_table = CharTable::Default,
                "ascii" => config.character_table = CharTable::Ascii,
                "codepage-1047" => config.character_table = CharTable::Codepage1047,
                "codepage-437" => config.character_table = CharTable::Codepage437,
                "braille" => config.character_table = CharTable::Braille,
                _ => {
                    eprintln!("error: invalid value '{}' for '--character-table <FORMAT>'\n  [possible values: default, ascii, codepage-1047, codepage-437, braille]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--color-scheme" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--color-scheme <FORMAT>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "default" => config.color_scheme = ColorScheme::Default,
                "gradient" => config.color_scheme = ColorScheme::Gradient,
                v => {
                    eprintln!("error: invalid value '{}' for '--color-scheme <FORMAT>'\n  [possible values: default, gradient]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--color-scheme=") {
            let v = &arg["--color-scheme=".len()..];
            match v {
                "default" => config.color_scheme = ColorScheme::Default,
                "gradient" => config.color_scheme = ColorScheme::Gradient,
                _ => {
                    eprintln!("error: invalid value '{}' for '--color-scheme <FORMAT>'\n  [possible values: default, gradient]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--panels" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--panels <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            let val_str = &args[i];
            if val_str == "auto" {
                config.panels = Panels::Auto;
            } else if val_str == "0" {
                eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                process::exit(1);
            } else if let Ok(n) = val_str.parse::<usize>() {
                config.panels = Panels::Fixed(n);
            } else {
                eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string", val_str);
                process::exit(1);
            }
            panels_set = true;
        } else if arg.starts_with("--panels=") {
            let val_str = &arg["--panels=".len()..];
            if val_str == "auto" {
                config.panels = Panels::Auto;
            } else if val_str == "0" {
                eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                process::exit(1);
            } else if let Ok(n) = val_str.parse::<usize>() {
                config.panels = Panels::Fixed(n);
            } else {
                eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string", val_str);
                process::exit(1);
            }
            panels_set = true;
        } else if arg == "-g" || arg == "--group-size" || arg == "--groupsize" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--group-size <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "1" => config.group_size = 1,
                "2" => config.group_size = 2,
                "4" => config.group_size = 4,
                "8" => config.group_size = 8,
                v => {
                    eprintln!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("-g=") || arg.starts_with("--group-size=") || arg.starts_with("--groupsize=") {
            let idx = arg.find('=').unwrap();
            let v = &arg[idx + 1..];
            match v {
                "1" => config.group_size = 1,
                "2" => config.group_size = 2,
                "4" => config.group_size = 4,
                "8" => config.group_size = 8,
                _ => {
                    eprintln!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--endianness" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--endianness <FORMAT>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "little" => config.endianness = Endianness::Little,
                "big" => config.endianness = Endianness::Big,
                v => {
                    eprintln!("error: invalid value '{}' for '--endianness <FORMAT>'\n  [possible values: little, big]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--endianness=") {
            let v = &arg["--endianness=".len()..];
            match v {
                "little" => config.endianness = Endianness::Little,
                "big" => config.endianness = Endianness::Big,
                _ => {
                    eprintln!("error: invalid value '{}' for '--endianness <FORMAT>'\n  [possible values: little, big]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "-b" || arg == "--base" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--base <B>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "hexadecimal" | "hex" | "x" => config.base = Base::Hexadecimal,
                "binary" | "bin" | "b" => config.base = Base::Binary,
                "octal" | "oct" | "o" => config.base = Base::Octal,
                "decimal" | "dec" | "d" => config.base = Base::Decimal,
                _ => {
                    eprintln!("Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".");
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--base=") {
            let v = &arg["--base=".len()..];
            match v {
                "hexadecimal" | "hex" | "x" => config.base = Base::Hexadecimal,
                "binary" | "bin" | "b" => config.base = Base::Binary,
                "octal" | "oct" | "o" => config.base = Base::Octal,
                "decimal" | "dec" | "d" => config.base = Base::Decimal,
                _ => {
                    eprintln!("Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".");
                    process::exit(1);
                }
            }
        } else if arg == "--terminal-width" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--terminal-width <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            if let Ok(w) = args[i].parse::<usize>() {
                config.terminal_width = Some(w);
            } else {
                eprintln!("error: invalid value '{}' for '--terminal-width <N>'", args[i]);
                process::exit(2);
            }
            width_set = true;
        } else if arg.starts_with("--terminal-width=") {
            let v = &arg["--terminal-width=".len()..];
            if let Ok(w) = v.parse::<usize>() {
                config.terminal_width = Some(w);
            } else {
                eprintln!("error: invalid value '{}' for '--terminal-width <N>'", v);
                process::exit(2);
            }
            width_set = true;
        } else if arg == "--completion" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--completion <SHELL>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "bash" | "elvish" | "fish" | "powershell" | "zsh" => config.completion = Some(args[i].clone()),
                v => {
                    eprintln!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--completion=") {
            let v = &arg["--completion=".len()..];
            match v {
                "bash" | "elvish" | "fish" | "powershell" | "zsh" => config.completion = Some(v.to_string()),
                _ => {
                    eprintln!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--" {
            i += 1;
            if i < args.len() {
                config.file = Some(args[i].clone());
            }
            break;
        } else if arg.starts_with('-') && arg != "-" {
            eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", arg, arg, arg);
            process::exit(2);
        } else {
            config.file = Some(arg.clone());
        }

        i += 1;
    }

    if panels_set && width_set {
        eprintln!("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nUsage: executable --panels <N> [FILE]\n\nFor more information, try '--help'.");
        process::exit(2);
    }

    config
}

