    println!("\x1b[39m\x1b[36ma ASCII printable characters (0x20 - 0x7E)");
    println!("\x1b[39m\x1b[32m_ ASCII whitespace (0x09 - 0x0D, 0x20)");
    println!("\x1b[39m\x1b[32m• ASCII control characters (except NULL and whitespace)");
