                    process::exit(2);
                }
            }
        } else if arg == "-b" || arg == "--base" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--base <B>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "hexadecimal" | "hex" | "x" => config.base = Base::Hexadecimal,
                "binary" | "bin" | "b" => config.base = Base::Binary,
                "octal" | "oct" | "o" => config.base = Base::Octal,
                "decimal" | "dec" | "d" => config.base = Base::Decimal,
                _ => {
                    eprintln!("Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".");
                    process::exit(1);
                }
            }
        } else if arg.starts_with("--base=") {
            let v = &arg["--base=".len()..];
            match v {
                "hexadecimal" | "hex" | "x" => config.base = Base::Hexadecimal,
                "binary" | "bin" | "b" => config.base = Base::Binary,
                "octal" | "oct" | "o" => config.base = Base::Octal,
                "decimal" | "dec" | "d" => config.base = Base::Decimal,
                _ => {
                    eprintln!("Error: The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".");
                    process::exit(1);
                }
            }
        } else if arg == "--terminal-width" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--terminal-width <N>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            if let Ok(w) = args[i].parse::<usize>() {
                config.terminal_width = Some(w);
            } else {
                eprintln!("error: invalid value '{}' for '--terminal-width <N>'", args[i]);
                process::exit(2);
            }
            width_set = true;
        } else if arg.starts_with("--terminal-width=") {
            let v = &arg["--terminal-width=".len()..];
            if let Ok(w) = v.parse::<usize>() {
                config.terminal_width = Some(w);
            } else {
                eprintln!("error: invalid value '{}' for '--terminal-width <N>'", v);
                process::exit(2);
            }
            width_set = true;
        } else if arg == "--completion" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--completion <SHELL>' but none was supplied\n\nFor more information, try '--help'.");
                process::exit(2);
            }
            i += 1;
            match args[i].as_str() {
                "bash" | "elvish" | "fish" | "powershell" | "zsh" => config.completion = Some(args[i].clone()),
                v => {
                    eprintln!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg.starts_with("--completion=") {
            let v = &arg["--completion=".len()..];
            match v {
                "bash" | "elvish" | "fish" | "powershell" | "zsh" => config.completion = Some(v.to_string()),
                _ => {
                    eprintln!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v);
                    process::exit(2);
                }
            }
        } else if arg == "--" {
            i += 1;
            if i < args.len() {
                config.file = Some(args[i].clone());
            }
            break;
        } else if arg.starts_with('-') && arg != "-" {
            eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", arg, arg, arg);
            process::exit(2);
        } else {
            config.file = Some(arg.clone());
        }

        i += 1;
    }

    if panels_set && width_set {
        eprintln!("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nUsage: executable --panels <N> [FILE]\n\nFor more information, try '--help'.");
        process::exit(2);
    }

    config
}

