fn map_char(b: u8, table: CharTable) -> char {
    match table {
        CharTable::Default => match b {
            0x00 => '⋄',
            0x09..=0x0D => '_',
            0x20 => ' ',
            0x21..=0x7E => b as char,
            0x01..=0x08 | 0x0E..=0x1F | 0x7F => '•',
            0x80..=0xFF => '×',
        },
        CharTable::Ascii => match b {
            0x20..=0x7E => b as char,
            _ => '.',
        },
        CharTable::Codepage1047 => CP1047_MAP[b as usize],
        CharTable::Codepage437 => CP437_MAP[b as usize],
        CharTable::Braille => match b {
            0x00 => '⋄',
            0x01..=0x1F => BRAILLE_CTRL[(b - 1) as usize],
            0x20..=0x7E => b as char,
            0x7F => ' ',
            0x80..=0xFF => std::char::from_u32(0x2800 + (b - 0x80) as u32).unwrap_or('?'),
        },
    }
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

fn get_terminal_width() -> Option<usize> {
    let mut ws = WinSize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    unsafe {
        if ioctl(1, 0x5413, &mut ws) == 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

fn stdout_is_tty() -> bool {
    unsafe { isatty(1) != 0 }
}

fn raw_hex_width(base: Base, group_size: usize) -> usize {
    let digits_per_byte = match base {
        Base::Hexadecimal => 2,
        Base::Binary => 8,
        Base::Octal | Base::Decimal => 3,
    };
    8 * digits_per_byte + (8 / group_size - 1)
}

fn calc_row_width(
    n: usize,
    border: BorderStyle,
    show_pos: bool,
    show_char: bool,
    base: Base,
    group_size: usize,
) -> usize {
    let rhw = raw_hex_width(base, group_size);
    if border == BorderStyle::Unicode || border == BorderStyle::Ascii {
        let mut w = 1; // left border
        if show_pos {
            w += 9;
        }
        w += n * (rhw + 2) + (n - 1);
        if show_char {
            w += 1 + n * 8 + (n - 1);
        }
        w += 1; // right border
        w
    } else {
        let mut w = if show_pos { 11 } else { 2 };
        w += n * rhw + (n - 1) * 3 + 2;
        if show_char {
            w += n * 8 + (n - 1) * 1 + 1;
        }
        w
    }
}

fn determine_panels(config: &Config) -> usize {
    match config.panels {
        Panels::Fixed(n) => n,
        Panels::Auto => {
            let target_width = if let Some(w) = config.terminal_width {
                w
            } else if stdout_is_tty() {
                get_terminal_width().unwrap_or(80)
            } else {
                80
            };

            let mut n = 1;
            while calc_row_width(
                n + 1,
                config.border_style,
                config.show_position,
                config.show_characters,
                config.base,
                config.group_size,
            ) <= target_width
            {
                n += 1;
            }
            n
        }
    }
}

fn use_colors(config: &Config) -> bool {
    let no_color = env::var("NO_COLOR").map(|s| !s.is_empty()).unwrap_or(false);
    match config.color_mode {
        ColorMode::Never => false,
        ColorMode::Force => true,
        ColorMode::Always => !no_color,
        ColorMode::Auto => !no_color && stdout_is_tty(),
    }
}

fn format_byte(b: u8, base: Base) -> String {
    match base {
        Base::Hexadecimal => format!("{:02x}", b),
        Base::Binary => format!("{:08b}", b),
        Base::Octal => format!("{:03o}", b),
        Base::Decimal => format!("{:03}", b),
    }
}

fn run_include(file_arg: Option<&str>, skip: Option<i64>, length: Option<u64>) {
    let mut input: Box<dyn Read> = if let Some(path) = file_arg {
        if path == "-" {
            Box::new(io::stdin())
        } else {
            match File::open(path) {
                Ok(f) => Box::new(f),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
    } else {
        Box::new(io::stdin())
    };

    if let Some(s) = skip {
        if s > 0 {
            let mut dummy = vec![0u8; s as usize];
            let _ = input.read_exact(&mut dummy);
        }
    }

    let mut data = Vec::new();
    if let Some(len) = length {
        let mut limited = input.take(len);
        let _ = limited.read_to_end(&mut data);
    } else {
        let _ = input.read_to_end(&mut data);
    }

    let is_file = file_arg.is_some() && file_arg.unwrap() != "-";
    if is_file {
        let path_str = file_arg.unwrap();
        let filename = std::path::Path::new(path_str)
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| path_str.to_string());

        let var_name: String = filename
            .chars()
            .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
            .collect();

        println!("unsigned char {}[] = {{", var_name);
        for chunk in data.chunks(12) {
            let formatted: Vec<String> = chunk.iter().map(|b| format!("0x{:02x}", b)).collect();
            let mut line = formatted.join(", ");
            let is_last_chunk = data.as_ptr_range().end == chunk.as_ptr_range().end;
            if !is_last_chunk {
                line.push(',');
            }
            println!("  {}", line);
        }
        println!("}};");
        println!("unsigned int {}_len = {};", var_name, data.len());
    } else {
        for chunk in data.chunks(12) {
            let formatted: Vec<String> = chunk.iter().map(|b| format!("0x{:02x}", b)).collect();
            let line = formatted.join(", ");
            println!("  {}", line);
        }
    }
}

fn main() {
    let config = parse_args();

    if config.print_color_table {
        print_color_table();
        return;
    }

    if let Some(ref shell) = config.completion {
        print_completion(shell);
        return;
    }

    if config.include {
        run_include(config.file.as_deref(), config.skip, config.length);
        return;
    }

    let is_colors = use_colors(&config);
    let panels = determine_panels(&config);

    // Open file or stdin
    let (reader, file_len): (Box<dyn Read>, Option<u64>) = if let Some(ref path) = config.file {
        if path == "-" {
            (Box::new(BufReader::new(io::stdin())), None)
        } else {
            match File::open(path) {
                Ok(f) => {
                    let len = f.metadata().ok().map(|m| m.len());
                    (Box::new(BufReader::new(f)), len)
                }
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
    } else {
        (Box::new(BufReader::new(io::stdin())), None)
    };

    let mut actual_reader = reader;

    // Handle skip
    let mut initial_file_pos: u64 = 0;
    if let Some(s) = config.skip {
        if s < 0 {
            let neg_abs = (-s) as u64;
            if let Some(flen) = file_len {
                if neg_abs <= flen {
                    let seek_pos = flen - neg_abs;
                    initial_file_pos = seek_pos;
                    let mut file_opt: Option<File> = None;
                    if let Some(ref path) = config.file {
                        if path != "-" {
                            if let Ok(mut f) = File::open(path) {
                                if f.seek(SeekFrom::Start(seek_pos)).is_ok() {
                                    file_opt = Some(f);
                                }
                            }
                        }
                    }
                    if let Some(f) = file_opt {
                        actual_reader = Box::new(BufReader::new(f));
                    } else {
                        eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                        process::exit(1);
                    }
                } else {
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    process::exit(1);
                }
            } else {
                eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                process::exit(1);
            }
        } else if s > 0 {
            let pos_bytes = s as u64;
            initial_file_pos = pos_bytes;
            let mut seeked = false;
            if let Some(ref path) = config.file {
                if path != "-" {
                    if let Ok(mut f) = File::open(path) {
                        if f.seek(SeekFrom::Start(pos_bytes)).is_ok() {
                            actual_reader = Box::new(BufReader::new(f));
                            seeked = true;
                        }
                    }
                }
            }
            if !seeked {
                let mut dummy = vec![0u8; pos_bytes as usize];
                let _ = actual_reader.read_exact(&mut dummy);
            }
        }
    }

    let mut final_reader: Box<dyn Read> = if let Some(len) = config.length {
        Box::new(actual_reader.take(len))
    } else {
        actual_reader
    };

    let bytes_per_line = panels * 8;
    let rhw = raw_hex_width(config.base, config.group_size);

    let offset_color = get_offset_color();

    // Border strings
    let (top_left, top_div, top_right, horiz, bottom_left, bottom_div, bottom_right, side, pos_div, panel_div, char_div, char_panel_div) = match config.border_style {
        BorderStyle::Unicode => ("┌", "┬", "┐", "─", "└", "┴", "┘", "│", "│", "┊", "│", "┊"),
        BorderStyle::Ascii => ("+", "+", "+", "-", "+", "+", "+", "|", "|", "|", "|", "|"),
        BorderStyle::None => ("", "", "", "", "", "", "", " ", "  ", "   ", "  ", " "),
    };

    let print_top_border = |out: &mut io::StdoutLock| {
        if config.border_style == BorderStyle::None {
            return;
        }
        let _ = write!(out, "{}", top_left);
        if config.show_position {
            for _ in 0..8 {
                let _ = write!(out, "{}", horiz);
            }
            let _ = write!(out, "{}", top_div);
        }
        for p in 0..panels {
            if p > 0 {
                let _ = write!(out, "{}", top_div);
            }
            for _ in 0..(rhw + 2) {
                let _ = write!(out, "{}", horiz);
            }
        }
        if config.show_characters {
            let _ = write!(out, "{}", top_div);
            for p in 0..panels {
                if p > 0 {
                    let _ = write!(out, "{}", top_div);
                }
                for _ in 0..8 {
                    let _ = write!(out, "{}", horiz);
                }
            }
        }
        let _ = writeln!(out, "{}", top_right);
    };

    let print_bottom_border = |out: &mut io::StdoutLock| {
        if config.border_style == BorderStyle::None {
            return;
        }
        let _ = write!(out, "{}", bottom_left);
        if config.show_position {
            for _ in 0..8 {
                let _ = write!(out, "{}", horiz);
            }
            let _ = write!(out, "{}", bottom_div);
        }
        for p in 0..panels {
            if p > 0 {
                let _ = write!(out, "{}", bottom_div);
            }
            for _ in 0..(rhw + 2) {
                let _ = write!(out, "{}", horiz);
            }
        }
        if config.show_characters {
            let _ = write!(out, "{}", bottom_div);
            for p in 0..panels {
                if p > 0 {
                    let _ = write!(out, "{}", bottom_div);
                }
                for _ in 0..8 {
                    let _ = write!(out, "{}", horiz);
                }
            }
        }
        let _ = writeln!(out, "{}", bottom_right);
    };

    let stdout = io::stdout();
    let mut out = stdout.lock();

    // Read all data into chunks
    let mut buffer = vec![0u8; bytes_per_line];
    let mut rows: Vec<Vec<u8>> = Vec::new();

    loop {
        let mut bytes_read = 0;
        while bytes_read < bytes_per_line {
            match final_reader.read(&mut buffer[bytes_read..]) {
                Ok(0) => break,
                Ok(n) => bytes_read += n,
                Err(_) => break,
            }
        }
        if bytes_read == 0 {
            break;
        }
        rows.push(buffer[..bytes_read].to_vec());
    }

    if rows.is_empty() {
        print_top_border(&mut out);
        let _ = write!(out, "{}", side);
        if config.show_position {
            let _ = write!(out, "        {}", pos_div);
        }
        let content_space = if config.border_style == BorderStyle::None { rhw } else { rhw + 2 };
        let msg = "No content";
        let pad_len = if content_space >= msg.len() + 1 { content_space - 1 - msg.len() } else { 0 };
        let _ = write!(out, " {}{}", msg, " ".repeat(pad_len));

        for _p in 1..panels {
            let _ = write!(out, "{}", panel_div);
            let sp_len = if config.border_style == BorderStyle::None { rhw } else { rhw + 2 };
            let _ = write!(out, "{}", " ".repeat(sp_len));
        }

        if config.show_characters {
            let _ = write!(out, "{}", char_div);
            for p in 0..panels {
                if p > 0 {
                    let _ = write!(out, "{}", char_panel_div);
                }
                let _ = write!(out, "        ");
            }
        }
        let _ = writeln!(out, "{}", side);
        print_bottom_border(&mut out);
        return;
    }

    print_top_border(&mut out);

    let mut current_offset = initial_file_pos;
    let mut last_row: Option<Vec<u8>> = None;
    let mut in_squeezing = false;

    let format_data_row = |row: &[u8], offset: u64, out: &mut io::StdoutLock| {
        let pos_val = config.display_offset.wrapping_add(offset);
        let _ = write!(out, "{}", side);

        if config.show_position {
            if is_colors {
                let _ = write!(out, "{}{:08x}\x1b[39m{}", offset_color, pos_val, pos_div);
            } else {
                let _ = write!(out, "{:08x}{}", pos_val, pos_div);
            }
        }

        for p in 0..panels {
            if p > 0 {
                let _ = write!(out, "{}", panel_div);
            }
            if config.border_style != BorderStyle::None {
                let _ = write!(out, " ");
            }

            let start_idx = p * 8;
            let end_idx = (start_idx + 8).min(row.len());
            let panel_bytes = if start_idx < row.len() { &row[start_idx..end_idx] } else { &[] };

            if is_colors {
                let mut current_color: Option<String> = None;
                let group_size = config.group_size;
                let num_groups = 8 / group_size;

                for g in 0..num_groups {
                    let g_start = g * group_size;
                    let g_end = (g_start + group_size).min(panel_bytes.len());

                    if g_start < panel_bytes.len() {
                        let mut g_bytes = panel_bytes[g_start..g_end].to_vec();
                        if config.endianness == Endianness::Little {
                            g_bytes.reverse();
                        }

                        for (_b_idx, &b) in g_bytes.iter().enumerate() {
                            let col = get_byte_color(b, &config);
                            if current_color.as_ref() != Some(&col) {
                                let _ = write!(out, "{}", col);
                                current_color = Some(col);
                            }
                            let formatted = format_byte(b, config.base);
                            let _ = write!(out, "{}", formatted);
                        }

                        if g + 1 < num_groups {
                            let _ = write!(out, " ");
                        }
                    }
                }

                // Pad missing spaces in hex panel
                let present_group_chars = {
                    let mut char_count = 0;
                    for g in 0..num_groups {
                        let g_start = g * group_size;
                        let g_end = (g_start + group_size).min(panel_bytes.len());
                        if g_start < panel_bytes.len() {
                            let g_bytes_len = g_end - g_start;
                            let digits_per_byte = match config.base {
                                Base::Hexadecimal => 2,
                                Base::Binary => 8,
                                Base::Octal | Base::Decimal => 3,
                            };
                            char_count += g_bytes_len * digits_per_byte;
                            if g + 1 < num_groups {
                                char_count += 1;
                            }
                        }
                    }
                    char_count
                };

                let missing_spaces = if rhw >= present_group_chars { rhw - present_group_chars } else { 0 };
                let _ = write!(out, "{}", " ".repeat(missing_spaces));

                if current_color.is_some() {
                    let _ = write!(out, "\x1b[39m");
                }
            } else {
                let group_size = config.group_size;
                let num_groups = 8 / group_size;
                let mut written_chars = 0;

                for g in 0..num_groups {
                    let g_start = g * group_size;
                    let g_end = (g_start + group_size).min(panel_bytes.len());

                    if g_start < panel_bytes.len() {
                        let mut g_bytes = panel_bytes[g_start..g_end].to_vec();
                        if config.endianness == Endianness::Little {
                            g_bytes.reverse();
                        }

                        for &b in &g_bytes {
                            let formatted = format_byte(b, config.base);
                            let _ = write!(out, "{}", formatted);
                            written_chars += formatted.len();
                        }

                        if g + 1 < num_groups {
                            let _ = write!(out, " ");
                            written_chars += 1;
                        }
                    }
                }

                let missing_spaces = if rhw >= written_chars { rhw - written_chars } else { 0 };
                let _ = write!(out, "{}", " ".repeat(missing_spaces));
            }

            if config.border_style != BorderStyle::None {
                let _ = write!(out, " ");
            }
        }

        if config.show_characters {
            let _ = write!(out, "{}", char_div);
            for p in 0..panels {
                if p > 0 {
                    let _ = write!(out, "{}", char_panel_div);
                }

                let start_idx = p * 8;
                let end_idx = (start_idx + 8).min(row.len());
                let panel_bytes = if start_idx < row.len() { &row[start_idx..end_idx] } else { &[] };

                if is_colors {
                    let mut current_color: Option<String> = None;
                    for &b in panel_bytes {
                        let col = get_byte_color(b, &config);
                        if current_color.as_ref() != Some(&col) {
                            let _ = write!(out, "{}", col);
                            current_color = Some(col);
                        }
                        let ch = map_char(b, config.character_table);
                        let _ = write!(out, "{}", ch);
                    }
                    let missing_chars = 8 - panel_bytes.len();
                    let _ = write!(out, "{}", " ".repeat(missing_chars));
                    if current_color.is_some() {
                        let _ = write!(out, "\x1b[39m");
                    }
                } else {
                    for &b in panel_bytes {
                        let ch = map_char(b, config.character_table);
                        let _ = write!(out, "{}", ch);
                    }
                    let missing_chars = 8 - panel_bytes.len();
                    let _ = write!(out, "{}", " ".repeat(missing_chars));
                }
            }
        }

        let _ = writeln!(out, "{}", side);
    };

    let print_squeezed_row = |out: &mut io::StdoutLock| {
        let _ = write!(out, "{}", side);
        if config.show_position {
            let _ = write!(out, "*       {}", pos_div);
        }
        for p in 0..panels {
            if p > 0 {
                let _ = write!(out, "{}", panel_div);
            }
            let sp_len = if config.border_style == BorderStyle::None { rhw } else { rhw + 2 };
            let _ = write!(out, "{}", " ".repeat(sp_len));
        }
        if config.show_characters {
            let _ = write!(out, "{}", char_div);
            for p in 0..panels {
                if p > 0 {
                    let _ = write!(out, "{}", char_panel_div);
                }
                let _ = write!(out, "        ");
            }
        }
        let _ = writeln!(out, "{}", side);
    };

    let print_empty_offset_row = |offset: u64, out: &mut io::StdoutLock| {
        let pos_val = config.display_offset.wrapping_add(offset);
        let _ = write!(out, "{}", side);
        if config.show_position {
            if is_colors {
                let _ = write!(out, "{}{:08x}\x1b[39m{}", offset_color, pos_val, pos_div);
            } else {
                let _ = write!(out, "{:08x}{}", pos_val, pos_div);
            }
        }
        for p in 0..panels {
            if p > 0 {
                let _ = write!(out, "{}", panel_div);
            }
            let sp_len = if config.border_style == BorderStyle::None { rhw } else { rhw + 2 };
            let _ = write!(out, "{}", " ".repeat(sp_len));
        }
        if config.show_characters {
            let _ = write!(out, "{}", char_div);
            for p in 0..panels {
                if p > 0 {
                    let _ = write!(out, "{}", char_panel_div);
                }
                let _ = write!(out, "        ");
            }
        }
        let _ = writeln!(out, "{}", side);
    };

    for row in &rows {
        if config.squeezing && row.len() == bytes_per_line && last_row.as_ref() == Some(row) {
            if !in_squeezing {
                print_squeezed_row(&mut out);
                in_squeezing = true;
            }
        } else {
            in_squeezing = false;
            format_data_row(row, current_offset, &mut out);
            last_row = Some(row.clone());
        }
        current_offset += row.len() as u64;
    }

    if in_squeezing {
        if config.show_position {
            print_empty_offset_row(current_offset, &mut out);
        } else {
            print_squeezed_row(&mut out);
        }
    }

    print_bottom_border(&mut out);
}
EOF"}

